import{_ as e,c as a,o as r,a0 as t}from"./chunks/framework.DKRgXLPU.js";const o=JSON.parse('{"title":"Referencia rápida del juego mental","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/es/summary-sheet.md","filePath":"public/downloads/es/summary-sheet.md"}');const i=e({name:"public/downloads/es/summary-sheet.md"},[["render",function(e,o,i,n,s,l){return r(),a("div",null,[...o[0]||(o[0]=[t('<h1 id="referencia-rapida-del-juego-mental" tabindex="-1">Referencia rápida del juego mental <a class="header-anchor" href="#referencia-rapida-del-juego-mental" aria-label="Permalink to &quot;Referencia rápida del juego mental&quot;">​</a></h1><p><strong>Academia de Petanca - Resumen de una página</strong></p><hr><h2 id="la-zona-estado-de-flujo" tabindex="-1">La zona/estado de flujo <a class="header-anchor" href="#la-zona-estado-de-flujo" aria-label="Permalink to &quot;La zona/estado de flujo&quot;">​</a></h2><p><strong>Dos modos de la mente:</strong></p><table tabindex="0"><thead><tr><th>Modo de planificación</th><th>Modo de ejecución</th></tr></thead><tbody><tr><td>Analiza el terreno</td><td>Confía en tu cuerpo</td></tr><tr><td>Elige la estrategia</td><td>No pienses</td></tr><tr><td>Evaluar riesgos</td><td>Momento presente</td></tr><tr><td>Tomar decisiones</td><td>Ejecución automática</td></tr></tbody></table><p><strong>El cambio:</strong> Planificar antes, fluir durante</p><hr><h2 id="critico-interno-vs-coach-interno" tabindex="-1">Crítico interno vs. Coach interno <a class="header-anchor" href="#critico-interno-vs-coach-interno" aria-label="Permalink to &quot;Crítico interno vs. Coach interno&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Crítico Interno ❌</th><th>Coach Interno ✅</th></tr></thead><tbody><tr><td>&quot;¡Eso fue terrible!&quot;</td><td>&quot;¿Qué puedo aprender?&quot;</td></tr><tr><td>&quot;Siempre la cagas&quot;</td><td>&quot;Siguiente disparo, nuevo comienzo&quot;</td></tr><tr><td>&quot;Todos te están viendo fracasar&quot;</td><td>&quot;Ya lo he hecho antes&quot;</td></tr><tr><td>&quot;No eres lo suficientemente bueno&quot;</td><td>&quot;Confía en el proceso&quot;</td></tr></tbody></table><p><strong>Reencuadrar:</strong> Pausa → Reencuadrar → Reiniciar → Reenfocar</p><hr><h2 id="reinicio-de-3-respiraciones" tabindex="-1">Reinicio de 3 respiraciones <a class="header-anchor" href="#reinicio-de-3-respiraciones" aria-label="Permalink to &quot;Reinicio de 3 respiraciones&quot;">​</a></h2><p><strong>Utilizar después de errores o presión:</strong></p><ol><li><strong>Respiración 1:</strong> Nota la tensión (¿dónde?)</li><li><strong>Respiración 2:</strong> Libera la tensión (suelta)</li><li><strong>Respiración 3:</strong> Reenfocar (esta toma, ahora)</li></ol><hr><h2 id="rutina-previa-al-disparo" tabindex="-1">Rutina previa al disparo <a class="header-anchor" href="#rutina-previa-al-disparo" aria-label="Permalink to &quot;Rutina previa al disparo&quot;">​</a></h2><p><strong>La misma rutina, en cada toma:</strong></p><ol><li><strong>Visualizar</strong> - Ver la toma</li><li><strong>Respira</strong> - Una respiración profunda</li><li><strong>Ancla</strong> - Toca la bola, siente el peso</li><li><strong>Ejecutar</strong> - Confiar y lanzar</li></ol><hr><h2 id="protocolo-de-recuperacion-de-errores" tabindex="-1">Protocolo de recuperación de errores <a class="header-anchor" href="#protocolo-de-recuperacion-de-errores" aria-label="Permalink to &quot;Protocolo de recuperación de errores&quot;">​</a></h2><p><strong>Después de un mal tiro:</strong></p><ol><li><strong>Reconocer</strong> - &quot;No salió como estaba previsto&quot;</li><li><strong>Liberación</strong> - Reinicio físico (sacúdelo)</li><li><strong>Reenfoque</strong> - &quot;La siguiente toma es nueva&quot;</li><li><strong>Ejecutar</strong> - Confía en tu rutina</li></ol><hr><h2 id="practica-de-esta-semana" tabindex="-1">Práctica de esta semana <a class="header-anchor" href="#practica-de-esta-semana" aria-label="Permalink to &quot;Práctica de esta semana&quot;">​</a></h2><p><strong>Elige UNA técnica:</strong></p><ul><li>[ ] Reinicio de 3 respiraciones después de cada error</li><li>[ ] Rutina previa al lanzamiento en cada lanzamiento</li><li>[ ] Reformular un pensamiento del Crítico Interno por sesión</li><li>[ ] Practique el cambio entre el modo planificación y el modo ejecución</li></ul><hr><h2 id="sigue-tu-progreso" tabindex="-1">Sigue tu progreso <a class="header-anchor" href="#sigue-tu-progreso" aria-label="Permalink to &quot;Sigue tu progreso&quot;">​</a></h2><p><strong>Aviso:</strong></p><ul><li>¿Cuándo te sientes más en fluidez?</li><li>¿Qué es lo que desencadena tu crítico interno?</li><li>¿Qué técnica te ayuda más?</li><li>¿Cómo cambia tu rendimiento?</li></ul><hr><h2 id="principios-clave" tabindex="-1">Principios clave <a class="header-anchor" href="#principios-clave" aria-label="Permalink to &quot;Principios clave&quot;">​</a></h2><ol><li><strong>El flujo es accesible</strong>: puedes aprender a ingresar a él de manera constante</li><li><strong>Tu voz interior importa</strong> - Entrénate, no critiques</li><li><strong>Las herramientas simples funcionan</strong>: 3 respiraciones, una rutina, un reinicio</li><li><strong>La práctica es clave</strong>: las habilidades mentales necesitan entrenamiento como las habilidades técnicas.</li></ol><hr><h2 id="recursos" tabindex="-1">Recursos <a class="header-anchor" href="#recursos" aria-label="Permalink to &quot;Recursos&quot;">​</a></h2><p><strong>Continúa aprendiendo en carreau.app:</strong></p><ul><li>La Zona - Análisis profundo del estado de flujo</li><li>Fortalecimiento mental: gestión avanzada de la presión</li><li>Plantilla de objetivos: Estructura tu desarrollo</li><li>Plantilla de diario: sigue tu progreso</li></ul><hr><p><strong>Recuerda:</strong> El entrenamiento mental no se trata de pensar positivamente. Se trata de técnicas prácticas que te ayudarán a acceder a tu mejor rendimiento bajo presión.</p><hr><p><em>Academia de Petanca - Desarrollo de jugadores de élite</em><em>carreau.app</em></p>',42)])])}]]);export{o as __pageData,i as default};
